-- NOVA multi-tenant foundation. Apply to a dedicated Supabase project only.
begin;
create extension if not exists pgcrypto;
create table if not exists public.organizations(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 2 and 120),currency text not null default 'INR' check(currency='INR'),created_at timestamptz not null default now());
create table if not exists public.branches(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,code text not null default 'MAIN',city text default 'Pune',state text default 'Maharashtra',is_default boolean not null default false,created_at timestamptz not null default now(),unique(organization_id,code),unique(organization_id,id));
create unique index if not exists branches_one_default_per_org on public.branches(organization_id) where is_default;
create table if not exists public.memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null default 'cashier' check(role in ('owner','manager','cashier','inventory','accountant')),is_active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,user_id));
create index if not exists memberships_user_idx on public.memberships(user_id,organization_id) where is_active;
create or replace function public.is_org_member(org uuid) returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.memberships m where m.organization_id=org and m.user_id=auth.uid() and m.is_active); $$;
create table if not exists public.products(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,sku text not null,barcode text,category text not null default 'Other',price numeric(12,2) not null default 0 check(price>=0),cost_price numeric(12,2) not null default 0 check(cost_price>=0),tax_rate numeric(5,2) not null default 0 check(tax_rate in(0,5,12,18,28)),is_active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,sku),unique(organization_id,id));
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,phone text,email text,gstin text,created_at timestamptz not null default now(),unique(organization_id,id));
create table if not exists public.suppliers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,name text not null,phone text,email text,gstin text,payment_terms text,is_active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,id));
create table if not exists public.inventory_levels(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid not null,product_id uuid not null,qty_on_hand integer not null default 0 check(qty_on_hand>=0),reorder_level integer not null default 0 check(reorder_level>=0),updated_at timestamptz not null default now(),foreign key(organization_id,branch_id) references public.branches(organization_id,id),foreign key(organization_id,product_id) references public.products(organization_id,id),unique(branch_id,product_id));
create table if not exists public.sales(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid not null,customer_id uuid,customer_name text not null default 'Walk-in customer',invoice_number text not null,payment_method text not null check(payment_method in('UPI','Cash','Card')),status text not null default 'paid' check(status in('paid','pending','refunded','void')),subtotal numeric(12,2) not null default 0,tax_total numeric(12,2) not null default 0,grand_total numeric(12,2) not null default 0,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),unique(organization_id,invoice_number),foreign key(organization_id,branch_id) references public.branches(organization_id,id),foreign key(organization_id,customer_id) references public.customers(organization_id,id));
create table if not exists public.documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,branch_id uuid,uploaded_by uuid not null references auth.users(id),category text not null check(category in('receipt','invoice','vendor_bill','purchase_proof','payment_proof','statement','tax_document','other')),title text not null check(length(trim(title)) between 1 and 180),original_file_name text not null,storage_path text not null unique,mime_type text not null,size_bytes bigint not null check(size_bytes>0 and size_bytes<=26214400),document_date date,counterparty text,reference_number text,amount numeric(14,2) check(amount is null or amount>=0),currency text not null default 'INR' check(currency='INR'),notes text,tags text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),foreign key(organization_id,branch_id) references public.branches(organization_id,id));
create index if not exists documents_org_date_idx on public.documents(organization_id,created_at desc);
create table if not exists public.platform_admins(user_id uuid primary key references auth.users(id) on delete cascade,access_level text not null default 'admin' check(access_level in('admin','support','read_only')),created_at timestamptz not null default now(),created_by uuid references auth.users(id));
create or replace function public.is_platform_admin() returns boolean language sql stable security definer set search_path=public,auth as $$ select exists(select 1 from public.platform_admins where user_id=auth.uid() and access_level='admin'); $$;
-- Enable RLS everywhere; tenant membership gates access.
do $$ declare t text; begin foreach t in array array['organizations','branches','memberships','products','customers','suppliers','inventory_levels','sales','documents','platform_admins'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy org_read on public.organizations for select to authenticated using(public.is_org_member(id) or public.is_platform_admin());
create policy branch_member_all on public.branches for all to authenticated using(public.is_org_member(organization_id) or public.is_platform_admin()) with check(public.is_org_member(organization_id));
create policy membership_read_self on public.memberships for select to authenticated using(user_id=auth.uid() or public.is_platform_admin());
create policy product_member_all on public.products for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy customer_member_all on public.customers for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy supplier_member_all on public.suppliers for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy inventory_member_all on public.inventory_levels for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy sales_member_all on public.sales for all to authenticated using(public.is_org_member(organization_id)) with check(public.is_org_member(organization_id));
create policy documents_member_select on public.documents for select to authenticated using(public.is_org_member(organization_id) or public.is_platform_admin());
create policy documents_member_insert on public.documents for insert to authenticated with check(public.is_org_member(organization_id) and uploaded_by=auth.uid());
create policy documents_owner_update on public.documents for update to authenticated using(exists(select 1 from public.memberships m where m.organization_id=documents.organization_id and m.user_id=auth.uid() and m.is_active and m.role in('owner','manager'))) with check(public.is_org_member(organization_id));
create policy documents_owner_delete on public.documents for delete to authenticated using(exists(select 1 from public.memberships m where m.organization_id=documents.organization_id and m.user_id=auth.uid() and m.is_active and m.role in('owner','manager')));
create policy platform_admin_self_read on public.platform_admins for select to authenticated using(user_id=auth.uid());
-- Secure private object storage. Names: <org_uuid>/<document_uuid>/<safe_filename>.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('nova-documents','nova-documents',false,26214400,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=26214400,allowed_mime_types=excluded.allowed_mime_types;
create policy nova_storage_select on storage.objects for select to authenticated using(bucket_id='nova-documents' and (public.is_org_member(((storage.foldername(name))[1])::uuid) or public.is_platform_admin()));
create policy nova_storage_insert on storage.objects for insert to authenticated with check(bucket_id='nova-documents' and public.is_org_member(((storage.foldername(name))[1])::uuid));
create policy nova_storage_update on storage.objects for update to authenticated using(bucket_id='nova-documents' and public.is_org_member(((storage.foldername(name))[1])::uuid)) with check(bucket_id='nova-documents' and public.is_org_member(((storage.foldername(name))[1])::uuid));
create policy nova_storage_delete on storage.objects for delete to authenticated using(bucket_id='nova-documents' and exists(select 1 from public.memberships m where m.organization_id=((storage.foldername(name))[1])::uuid and m.user_id=auth.uid() and m.is_active and m.role in('owner','manager')));
commit;
